import{_ as p,a0 as l,w as o,s as r,ao as d,I as t,x as n,a1 as i,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"如何在 RHEL 上设置 Linux RAID 1 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 RHEL 上设置 Linux RAID 1 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 RHEL 上设置 Linux RAID 1 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 RHEL 上设置 Linux RAID 1 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20161210 How to Setup Linux RAID 1 Device on RHEL","title":"如何在 RHEL 上设置 Linux RAID 1","tag":"201702","desc":""},"relativePath":"201702/20161210 How to Setup Linux RAID 1 Device on RHEL.md","filePath":"[post].md"}'),u={name:"201702/20161210 How to Setup Linux RAID 1 Device on RHEL.md"};function m(x,s,c,h,L,D){const a=l("Link");return o(),r("div",null,[s[13]||(s[13]=d(`<h1 id="如何在-rhel-上设置-linux-raid-1" tabindex="-1">如何在 RHEL 上设置 Linux RAID 1 <a class="header-anchor" href="#如何在-rhel-上设置-linux-raid-1" aria-label="Permalink to “如何在 RHEL 上设置 Linux RAID 1”">​</a></h1><h3 id="设置-linux-raid-1" tabindex="-1">设置 Linux RAID 1 <a class="header-anchor" href="#设置-linux-raid-1" aria-label="Permalink to “设置 Linux RAID 1”">​</a></h3><p>配置 LINUX RAID 1 非常重要，因为它提供了冗余性。</p><p>RAID 分区拥有高级功能，如冗余和更好的性能。所以让我们来说下如何实现 RAID，以及让我们来看看不同类型的 RAID：</p><ul><li>RAID 0（条带）：磁盘组合在一起，形成一个更大的驱动器。这以可用性为代价提供了更好的性能。如果 RAID 中的任何一块磁盘出现故障，则整个磁盘集将无法使用。最少需要两块磁盘。</li><li>RAID 1（镜像）：磁盘从一个复制到另一个，提供了冗余。如果一块磁盘发生故障，则另一块磁盘接管，它有另外一份原始磁盘的数据的完整副本。其缺点是写入时间慢。最少需要两块磁盘。</li><li>RAID 5（带奇偶校验的条带）：磁盘类似于 RAID 0，并且连接在一起以形成一个大型驱动器。这里的区别是，25％ 的磁盘用于奇偶校验位，这允许在单个磁盘发生故障时可以恢复磁盘。最少需要三块盘。</li></ul><p>让我们继续进行 Linux RAID 1 配置。</p><p>安装 Linux RAID 1 的要求：</p><p>1、系统中应该安装了 mdam，请用下面的命令确认。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@rhel1 ~]# rpm -qa | grep -i mdadm</span></span>
<span class="line"><span>mdadm-3.2.2-9.el6.x86_64</span></span>
<span class="line"><span>[root@rhel1 ~]#</span></span></code></pre></div><p>2、 系统应该连接了 2 块磁盘。</p><p>创建两个分区，一个磁盘一个分区（sdc、sdd），每个分区占据整块磁盘。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Disk /dev/sdc: 1073 MB, 1073741824 bytes</span></span>
<span class="line"><span>255 heads, 63 sectors/track, 130 cylinders</span></span>
<span class="line"><span>Units = cylinders of 16065 * 512 = 8225280 bytes</span></span>
<span class="line"><span>Sector size (logical/physical): 512 bytes / 512 bytes</span></span>
<span class="line"><span>I/O size (minimum/optimal): 512 bytes / 512 bytes</span></span>
<span class="line"><span>Disk identifier: 0x67cc8cfb</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Device Boot Start End Blocks Id System</span></span>
<span class="line"><span>/dev/sdc1 1 130 1044193+ 83 Linux</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Disk /dev/sdd: 1073 MB, 1073741824 bytes</span></span>
<span class="line"><span>255 heads, 63 sectors/track, 130 cylinders</span></span>
<span class="line"><span>Units = cylinders of 16065 * 512 = 8225280 bytes</span></span>
<span class="line"><span>Sector size (logical/physical): 512 bytes / 512 bytes</span></span>
<span class="line"><span>I/O size (minimum/optimal): 512 bytes / 512 bytes</span></span>
<span class="line"><span>Disk identifier: 0x0294382b</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Device Boot Start End Blocks Id System</span></span>
<span class="line"><span>/dev/sdd1 1 130 1044193+ 83 Linux</span></span></code></pre></div><hr><p>作者简介：</p><p>大家好！我是 Manmohan Mirkar。我很高兴见到你们！我在 10 多年前开始使用 Linux，我从来没有想过我会到今天这个地步。我的激情是帮助你们获取 Linux 知识。谢谢阅读！</p><hr>`,16)),t("p",null,[s[1]||(s[1]=n("via: ",-1)),i(a,{href:"http://www.linuxroutes.com/linux-raid-1/"},{default:e(()=>[...s[0]||(s[0]=[n("http://www.linuxroutes.com/linux-raid-1/",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=n("作者：",-1)),i(a,{href:"http://www.linuxroutes.com/author/admin/"},{default:e(()=>[...s[2]||(s[2]=[n("Manmohan Mirkar",-1)])]),_:1}),s[6]||(s[6]=n(" 译者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:e(()=>[...s[3]||(s[3]=[n("geekpi",-1)])]),_:1}),s[7]||(s[7]=n(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[4]||(s[4]=[n("wxy",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=n("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[8]||(s[8]=[n("LCTT",-1)])]),_:1}),s[11]||(s[11]=n(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:e(()=>[...s[9]||(s[9]=[n("Linux中国",-1)])]),_:1}),s[12]||(s[12]=n(" 荣誉推出",-1))])])}const f=p(u,[["render",m]]);export{b as __pageData,f as default};
